function makeDraft(spec: DraftSpec): BlogPost {
  const commonSections = [
    { heading: "Start by observing the pattern", paragraphs: [spec.focus, "Before changing settings or trying multiple cycles, note when the symptom begins, what the appliance was doing immediately before it, and whether it changes with normal use. A short, accurate symptom timeline gives a repair professional more value than a guess at the failed part.", "Compare the appliance with its normal behavior rather than with an assumed universal standard. An intermittent sound, temperature change, or cycle interruption may be more revealing when paired with the time of day, load size, door position, or weather conditions in the room.", "Use the owner’s manual for model-specific homeowner maintenance only. If the appliance has an error code, take a photo or write it down rather than clearing it repeatedly. This article is intended to help you make a safer decision, not to replace a diagnosis."] },
    { heading: "Safe checks homeowners can make", paragraphs: ["Look for obvious, external conditions: a door or drawer that cannot close, blocked airflow around an appliance, a normal filter that needs cleaning, an overloaded load, or an accessible setting changed by accident. Keep the area dry, clear, and well lit while you inspect.", "If the appliance is connected through a visible cord, look for obvious exterior damage without handling exposed wiring. For water-related symptoms, protect the floor and nearby cabinetry first. These observations support a better repair conversation without requiring disassembly.", "Do not use sharp tools, chemical drain cleaners, improvised wiring, or excessive force. Those shortcuts can harm the appliance, hide useful evidence, or create a safety risk. If the symptom involves heat, water, electricity, gas, or a sealed cooling system, a professional check is the right next step."] },
    { heading: "Why the same symptom can have several causes", paragraphs: ["Appliances protect themselves in different ways. A cycle may stop because a sensor, lock, temperature condition, airflow restriction, drain path, or control is outside its expected range. That is why replacing a commonly mentioned part from an online search often does not solve the actual issue.", "A problem can also appear to be one appliance concern while the surrounding conditions contribute: a crowded refrigerator vent, overloaded washer, damaged external vent, poor room ventilation, or a supply issue. Professional diagnosis considers both the appliance and the symptom pattern.", "The practical question is whether the appliance is stable and safe to use while you arrange help. If performance is changing, protect food, flooring, and nearby surfaces as appropriate, then avoid repeated use until you understand the cause."] },
    { heading: "Plan a more useful repair visit", paragraphs: ["Have the appliance brand, model number, approximate age, and a plain-language description ready. Mention the first time you noticed the issue, any sounds, odors, leaks, frost, heat changes, and error codes. This helps the visit start with the right information.", "If you have photos or a short video of a non-dangerous symptom, keep them available for the appointment. Do not recreate a safety issue just to document it. Clear notes about what changed and what still works normally are often enough.", "DAPL Appliance Repair serves Charlotte, Mint Hill, and nearby communities when route and appointment availability allow. The goal is clear, practical next-step guidance based on the appliance in front of you."] },
  ];
  return { ...spec, status: "scheduled", readingTime: "8 min read", intro: spec.focus, sections: commonSections, professionalHelp: ["The symptom is worsening, recurring, or preventing normal safe use.", "There is a leak, burning smell, smoke, sparking, gas odor, or loss of cooling.", "The basic external checks did not resolve the concern."], faqs: [{ question: "Can I keep using the appliance while I wait?", answer: "That depends on the symptom. Stop use for safety concerns, leaks, unstable cooling, burning smells, sparking, gas odor, or unusual heat." }, { question: "What should I have ready before booking?", answer: "The model number, the symptom timeline, error codes, and a note about sounds, odors, heat, water, frost, or cycle behavior are especially helpful." }], relatedLinks: [{ label: spec.service, href: spec.serviceHref }, { label: "Local service area", href: spec.areaHref }, { label: "Brand repair help", href: spec.brandHref }] };
}

export const draftBlogPosts = draftSpecs.map(makeDraft);
export const blogPosts: BlogPost[] = [
  ...publishedBlogPostSeeds.map((post) => ({ ...post, status: "published" as const, scheduledFor: post.publishedAt })),
  ...draftBlogPosts,
];
export type PublishedBlogPost = BlogPost & { status: "published"; publishedAt: string };
export const publishedBlogPosts = blogPosts.filter((post): post is PublishedBlogPost => post.status === "published" && Boolean(post.publishedAt));
function isScheduleLive(post: BlogPost, now = new Date()) {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "America/New_York", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(now).reduce<Record<string, string>>((out, part) => ({ ...out, [part.type]: part.value }), {});
  return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}` >= `${post.scheduledFor}T09:00`;
}
export function getPublicBlogPosts(now = new Date()) { return blogPosts.filter((post) => post.status === "published" || (post.status === "scheduled" && isScheduleLive(post, now))); }
export function getBlogPost(slug: string, now = new Date()) { return getPublicBlogPosts(now).find((post) => post.slug === slug); }
